<?php require __DIR__.'/../app/bootstrap.php';$u=require_seller();require_commerce();$title='Incoming orders';$orders=all('SELECT * FROM orders WHERE seller_id=? ORDER BY id DESC',[$u['id']]);require ROOT.'/app/workspace-start.php'; ?>
<div class="page-heading"><h1>Incoming Orders</h1><p>Prepare pickup and delivery orders for your customers.</p></div><section class="panel"><?php if(!$orders): ?><p class="empty">New customer orders will appear here.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Method</th><th>Total</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($orders as $order): ?><tr><td><?=e($order['reference'])?></td><td><?=e($order['customer_name'])?></td><td><?=e(ucfirst($order['fulfillment']))?></td><td><?=money((int)$order['total_paisa'])?></td><td><?=e(status_label($order))?></td><td><a class="pill compact" href="<?=e(url('seller/order.php?id='.$order['id']))?>">Manage →</a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><?php require ROOT.'/app/workspace-end.php'; ?>
